def fleet_band(depth=2):
    """One line at the foot of a shelf: where else the same hands have been."""
    r = "../" * depth
    links = " · ".join(
        f'<a href="{att(_FLEET_BY[i]["url"])}">{bi(th, _FLEET_BY[i]["name"])}</a>'
        for i, th, _, _en in _FLEET_BAND if i in _FLEET_BY)
    return (f'<p class="fleetband"><span class="fbl">{bi("ที่อื่นของเรา", "Elsewhere")}</span> '
            + links + f' · <a href="{r}elsewhere.html">' + bi("ทั้งหมด", "all of it") + ' →</a></p>')


def elsewhere_body():
    """/elsewhere.html — the roster itself, one card each, Thai first."""
    def cards(rows):
        out = []
        for i, th, th_note, en_note in rows:
            site = _FLEET_BY.get(i)
            if not site:
                continue
            out.append(f'<li><a href="{att(site["url"])}">{bi(th, site["name"])}</a>'
                       f'<span class="sub">{bi(th_note, en_note)}</span></li>')
        return '<ul class="fleetlist">' + "".join(out) + '</ul>'
    return (f'<h1>{bi("ที่อื่นของเรา", "Elsewhere from the same workshop")}</h1>'
            + '<p class="lede">'
            + bi("สารบัญและคลังอื่น ๆ ที่ทำด้วยมือเดียวกัน",
                 "The other directories and archives built by the same hands.")
            + '</p>'
            + cards(_FLEET_BAND + _FLEET_REST)
            + f'<h2>{bi("ผู้ช่วยและงานบริการ", "Assistants and services")}</h2>'
            + cards(_FLEET_SERVICES)
            + f'<p class="prov"><a href="{att(FLEET["canonical"])}">'
            + bi("รายชื่อทั้งหมดเป็น JSON", "the roster as JSON") + '</a></p>')


def yant_band(cat_key):
    """The tattoo shelf's porch: what wichaa's yant pages ARE to this shelf.

    Mot Dang lists where a yant is done and what it costs; wichaa holds the
    designs themselves, read from the Lanna manuscripts. The join is stated
    from this side with the fact that makes it true (WO-14): the paired-bird
    นกคู่ sold on Arak Road is the ยันต์สาริกาคู่ of manuscript 6985, a century
    apart; a single na — the cheapest line on a สำนัก's menu — is the smallest
    unit of the whole art, and /na holds 142 of them. Three things are sold
    under one word here, so the band ends with the sentence that separates
    them at the door. No prices in the band; the record carries those.
    """
    if cat_key != "tattoo":
        return ""
    return (
        '<div class="yantband">'
        f'<b>{bi("ก่อนเลือกลาย — ลายที่เลือกได้ไม่ใช่ของใหม่", "Before you choose — what you choose from is not new")}</b>'
        f'<p><a href="https://wichaa.net/yant" rel="noopener">wichaa.net/yant</a> — '
        + bi("ลายยันต์ล้านนา 36 ลายจากใบลาน จัดตามสรรพคุณ: นกคู่ที่ขายบนถนนอารักษ์คือ ยันต์สาริกาคู่ ในเล่ม 6985 ห่างกันราวร้อยปี",
             "36 Lanna yant designs from the manuscripts, by what each is for — the paired-bird นกคู่ sold on Arak Road is the ยันต์สาริกาคู่ of manuscript 6985, a century apart")
        + '</p><p><a href="https://wichaa.net/na" rel="noopener">wichaa.net/na</a> — '
        + bi("นะ 142 ตัว: นะตัวเดียวคือของถูกสุดในเมนูของสำนัก และเป็นหน่วยเล็กสุดของทั้งวิชา",
             "the 142 na — a single na is the cheapest line on a สำนัก's menu and the smallest unit of the whole art")
        + '</p><p><a href="https://sak-yant.nanobotco.workers.dev/" rel="noopener">'
        + bi("ยันต์ของคุณบอกอะไร", "What does your sak yant mean") + "</a> — "
        + bi("อ่านอักขระขอม ตัวเลข และสัตว์บนผิวของคุณ — บทความจากคลังใบลานเดียวกัน",
             "reading the Khom letters, the numerals and the animals already on your skin — from the same manuscript corpus")
        + "</p><p>"
        + bi("คำเดียวขายสามอย่าง: สำนักที่อาจารย์ลงคาถา · ร้านสักลาย · ร้านสักคิ้ว-สักปาก — ประโยคถามหน้าร้าน: ที่นี่มีอาจารย์ลงคาถาให้ไหมคะ/ครับ หรือสักลายอย่างเดียว",
             "One word, three trades: a สำนัก where an ajarn gives the katha · a studio that inks the design · a brow-and-lip shop — the sentence to ask at the shop: is there an ajarn here who gives the katha, or is it the design only?")
        + "</p></div>")


def cat_art_band(cat_key, prov_key, depth=2):
    """A wide strip of her hand-picked city art across the top of a shelf page.

    Day-salted like the hero, so shelf headers freshen with the morning walk.
    local=True throughout: a massage parlour in Siem Reap is a fine mood
    picture and the wrong header for a shelf that says Chiang Mai."""
    topic = CAT_ART_TOPIC.get(cat_key)
    if not topic:
        return ""
    hint = "yant" if cat_key == "tattoo" else None
    k = f"catband-{prov_key}-{cat_key}-{BUILD_DATE}"
    # THREE, not one. Same band, same height — the strip is divided, not added
    # to, so this costs no vertical space and no words. Three slots per shelf
    # is what lets art()'s round-robin actually reach the whole pool.
    #
    # This province's pictures first, then the ones tagged for the north at large,
    # then the dish-or-custom pictures tagged `elsewhere` (Nan, 2026-09-07: use ALL
    # the pictures). Never the other province: a Chiang Rai shelf headed by Chiang
    # Mai (Nan, 2026-09-28, "yes pls fix").
    picks = []

    def more(**kw):
        have = {x["slug"] for x in picks}
        picks.extend(q for q in art(topic=topic, n=3, key=k, **kw) if q["slug"] not in have)

    if hint:
        more(slug_has=hint, place=prov_key, not_topic=("people",), local=True)
    # The season we are standing in leads, where the pool has one: a rains
    # shelf in October, a cool-season one in December (สามฤดู, as the hero).
    _m = int(BUILD_DATE[5:7])
    _season = "hot" if _m in (3, 4, 5) else "rains" if 6 <= _m <= 10 else "cool"
    more(place=prov_key, season=_season, not_topic=("people",), local=True)
    for pl in (prov_key,) if prov_key in CENTRAL else (prov_key, "lanna"):
        if len(picks) < 3:
            more(place=pl, not_topic=("people",), local=True)
    if len(picks) < 3 and prov_key not in CENTRAL:
        more(place="elsewhere")
    picks = picks[:3]
    if not picks:
        return ""
    r = "../" * depth

    def one(q):
        img = (f'<img src="{r}site/{q["slug"]}.jpg" alt="{att(art_alt(q))}" '
               f'loading="lazy" width="{q.get("width") or 1000}" '
               f'height="{q.get("height") or 750}">')
        # Her pictures go to the place they show (NaN, 2026-09-28).
        if q.get("artist") == "NaN Peacock" and q.get("lat") is not None:
            return f'<a href="{r}{att(pics_layer.href_of(q).lstrip("/"))}">{img}</a>'
        return img
    imgs = "".join(one(q) for q in picks)
    # One chip for the strip. Every photographer and licence is on
    # /pictures.html, which is where the chip goes.
    chip = f'<a class="herocredit" href="{r}pictures.html">📷</a>'
    return f'<div class="catband n{len(picks)}">{imgs}{chip}</div>'


def art_alt(p):
    """What the picture shows, in both languages, or nothing at all.

    `alt=""` is the correct marking for decoration, and most of this art IS
    decoration sitting beside a label that already says the word. So the rule
    is: describe it only where a real description exists to describe it with —
    never a restatement of the heading next to it, never a guess at a frame
    nobody here has looked at. Credit for every one of them lives on
    /pictures.html, which is linked wherever they appear.
    """
    if p.get("caption_th") or p.get("caption_en"):
        return bi_text(p.get("caption_th", ""), p.get("caption_en", ""))
    d = (p.get("description") or "").strip()
    if not d or d.lower().startswith("photo i took"):
        return ""
    return d[:160]

BAND_PIC_SRC = ROOT / "assets" / "band"


def band_pic_file(pick):
    """Where the band's copy of a picture lives.

    The pool ships at its full size — 238 KB on average — which is right for a
    picture somebody has scrolled to and wrong for one at the very top of the
    front page on a mid-budget Android. importers/make_band_pics.py writes a
    520 px-wide copy into assets/band/ when Pillow is on the machine; this
    returns that copy when it exists and the full picture when it does not, so
    the band is never waiting on an optional step to work.
    """
    small = BAND_PIC_SRC / (pick["slug"] + ".jpg")
    return ("band/" if small.exists() else "site/") + pick["slug"] + ".jpg"


def own_strip(r, hero_file=None):
    """NaN's ride pictures of this place, beside whatever photograph leads the page.

    The lead photograph, when it is one of hers, is a byte copy of one of these
    picks, so the same file size marks it and it is not shown twice.
    """
    pics = OWN_BY_PLACE.get(r["id"]) or []
    if hero_file and (PHOTOS_SRC / hero_file).exists():
        _sz = (PHOTOS_SRC / hero_file).stat().st_size
        pics = [p for p in pics if (ROOT / "assets" / p["file"]).stat().st_size != _sz]
    if not pics:
        return ""
    # 40, not 6: the strip scrolls and loads lazily, and a market she walked
    # through carries a hundred frames (NaN 2026-10-11, Kamthieng amulet market).
    pics = sorted(pics, key=lambda p: (p.get("date") or "", p["slug"]), reverse=True)[:40]
    for p in pics:
        ART_USED[p["slug"]] = p
    imgs = "".join(
        f'<a href="../../{att(p["file"])}"><img src="../../{att(band_pic_file(p))}" '
        f'width="{int(p.get("width") or 900)}" height="{int(p.get("height") or 600)}" '
        f'alt="{att(art_alt(p))}" loading="lazy"></a>' for p in pics)
    days = sorted({p["date"] for p in pics if p.get("date")})
    when = " · ".join(datetime.date.fromisoformat(d).strftime("%-d %b %Y") for d in days)
    return (f'<figure class="ownpics"><div>{imgs}</div><figcaption>📷 '
            f'<a href="../../pictures.html">NaN Peacock</a>{" — " + when if when else ""}'
            f' · CC BY 4.0</figcaption></figure>')


def street_fig(r):
    """The street where this place stands, from streetphoto_layer; "" when none."""
    return streetphoto_layer.figure_html(r, STREET_PHOTOS.get(r["id"]), {
        "att": att, "bi": bi, "esc": esc, "bi_text": bi_text,
        "name_th": name_th, "name_en": name_en})


def street_view_btn(r):
    """Street view from the nearest harvested photo, from streetview_layer; "" when none."""
    return streetview_layer.button_html(r, {"att": att, "bi": bi, "bi_text": bi_text})


def _emph(s):
    """A history paragraph as safe markup: everything escaped, then the roads
    corpus's *…* emphasis (it marks an inference apart from the record) turned
    into <em>."""
    return re.sub(r"\*(.+?)\*", r"<em>\1</em>", esc(s))


def landmark_history(r):
    """A landmark's sourced history, English and Thai, as read prose.

    Businesses carry no blurb — a shop is its structured facts (Nan, 2026-09-06,
    tests/test_no_blurbs.py). A gate is not a shop: the story of how Tha Phae
    Gate was pulled down for a road in 1948 and rebuilt as the postcard forty
    years later is the thing a reader came for, and it is cited to the roads
    corpus, not composed here. Present only on records that carry `history`,
    which the business path never sets.
    """
    h = r.get("history") or {}
    if not h:
        return ""
    def paras(t):
        return [p.strip() for p in (t or "").split("\n\n") if p.strip()]
    en, th = paras(h.get("en")), paras(h.get("th"))
    rows = []
    for i in range(max(len(en), len(th))):
        _th = th[i] if i < len(th) else ""
        _en = en[i] if i < len(en) else ""
        rows.append("<p>%s</p>" % bi(_emph(_th), _emph(_en), raw=True))
    return ('<section class="history"><h2>%s</h2>%s</section>'
            % (bi("ประวัติ", "History"), "".join(rows)))


def landmark_gallery(r):
    """A landmark's photographs, beside the one that leads the page.

    The roads corpus's Commons pictures, copied to disk with each
    photographer and licence. Thumbnails link to the full frame; the caption
    names every photographer and licence, which CC BY-SA asks travel with the
    picture. own_strip() carries Nan's own field photographs of the same place
    separately, credited to her.
    """
    g = r.get("gallery") or []
    if not g:
        return ""
    imgs = []
    for im in g:
        thumb = im.get("thumb") or im["file"]
        _t = ", ".join(x for x in (im.get("author"), im.get("license")) if x)
        imgs.append('<a href="../../%s" title="%s"><img src="../../%s" '
                    'alt="%s" loading="lazy"></a>'
                    % (att(im["file"]), att(_t),
                       att(thumb), att(im.get("alt") or name_text(r))))
    authors = list(dict.fromkeys(im.get("author") for im in g if im.get("author")))
    lics = list(dict.fromkeys(im.get("license") for im in g if im.get("license")))
    cap = " · ".join(x for x in (", ".join(authors), " / ".join(lics),
                                 "Wikimedia Commons") if x)
    return ('<figure class="landmarkpics"><div>%s</div>'
            '<figcaption>📷 %s</figcaption></figure>'
            % ("".join(imgs), esc(cap)))


def band_credit(name):
    """A photographer's name as a 24-character chip.

    hero_credit()'s rule, reused: drop the parenthetical some Commons
    usernames carry, and when it still will not fit, cut on a word and mark
    the cut. The first draft cut mid-word and left "Adam Jones from Kelowna,
    BC," sitting under a photograph with a trailing comma.
    """
    a = re.sub(r"\s*\(.*?\)\s*", " ", (name or "")).strip()
    if a.lower() == "unknown":
        return ""
    if len(a) <= 24:
        return a
    cut = a[:23].rstrip()
    if " " in cut:
        cut = cut[:cut.rfind(" ")].rstrip()
    return cut.rstrip(" ,;·-") + "…"


_BAND_PLACE = None   # the names in assets/band/place/, listed once a process


def band_place_file(rec_id):
    """The band's copy of a place's own photograph, or the full one."""
    global _BAND_PLACE
    if _BAND_PLACE is None:
        # One listing, not a stat per place page (48 s of the build, 2026-10-10).
        d = BAND_PIC_SRC / "place"
        _BAND_PLACE = frozenset(os.listdir(d)) if d.is_dir() else frozenset()
    if rec_id + ".jpg" in _BAND_PLACE:
        return "band/place/" + rec_id + ".jpg"
    name = PHOTO_FILES.get(rec_id)
    return ("photos/" + name) if name else ""


# ---------------------------------------------------------------- reachability
# Most places here have no working website, and plenty of the ones that do have
# a site that has quietly stopped working. The living channel is nearly always a
# phone, a LINE id, or a Facebook page. So the page ranks channels by whether a
# person can actually get through, keeps an archived copy of a site that has
# stopped answering instead of sending anyone into a security warning, and says
# plainly that this page holds the record when nothing else does.
# Verdicts come from importers/check_links.py — see data/linkhealth.json.
_health_path = ROOT / "data" / "linkhealth.json"
_health = json.loads(_health_path.read_text()) if _health_path.exists() else {}
LINK_HEALTH = _health.get("links", {})
LINK_HEALTH_DATE = _health.get("generated", "")

# Ground heights at the pins of the peak, viewpoint and waterfall shelves,
# read from the elevation archive by importers/build_terrain.py (WO-37c) —
# median of the nine cells around each pin, the model's reading, dated.
# A mapper's own `ele` on a record is a person's measurement at the spot and
# outranks this wherever it exists (known_facts renders that precedence).
# Absence of the file is the usual supported state: no chip, no line, no gap.
_terrain_h_path = ROOT / "data" / "terrain_heights.json"
_terrain_h = (json.loads(_terrain_h_path.read_text())
              if _terrain_h_path.exists() else {})
TERRAIN_HEIGHTS = _terrain_h.get("heights", {})
TERRAIN_HEIGHTS_DATE = _terrain_h.get("read", "")

# The claiming layer: an owner enters their own contact facts free at
# /claim.html, publishing instantly via worker/worker.js (Cloudflare KV, no
# accounts). importers/sync_claims.py pulls the live set into data/claims.json
# before each build — see that file's docstring for why this is two steps.
CLAIMS_WORKER_URL = "https://mot-dang-claims.nanobotco.workers.dev"
_claims_path = ROOT / "data" / "claims.json"
_claims_doc = json.loads(_claims_path.read_text()) if _claims_path.exists() else {}
CLAIMS = _claims_doc.get("claims", {})

# The facet layer: what makes one branch of a chain different from the next.
# data/facets.json is the whole schema — labels, icons, and the question to ask
# a passer-by. importers/import_fixtures.py fills what evidence allows; the rest
# arrives by claim. Keyed by record.sub, so a shelf of convenience stores gets
# the convenience row and nothing else does — or by record.cat, for a category
# whose crawl yields no subs at all to key on. See _applies_note in the schema.
_facets_doc = json.loads((ROOT / "data" / "facets.json").read_text())
FACET_SETS = _facets_doc["sets"]
FACET_SET_BY_SUB = {sub: s for s in FACET_SETS for sub in s.get("appliesTo", [])}
FACET_SET_BY_CAT = {cat: s for s in FACET_SETS for cat in s.get("appliesToCat", [])}
FACET_DEF = {s["key"]: {f["key"]: f for f in s["facets"]} for s in FACET_SETS}

# Verdicts that mean: do not send a person here.
BROKEN = {"tls", "dns", "down", "timeout", "gone", "http-error", "server-error",
          "parked", "empty", "error"}

SOCIAL_HOSTS = {
    "facebook.com": "facebook", "m.facebook.com": "facebook", "web.facebook.com": "facebook",
    "fb.com": "facebook", "fb.me": "facebook", "instagram.com": "instagram",
    "line.me": "line", "lin.ee": "line", "tiktok.com": "tiktok",
    "twitter.com": "x", "x.com": "x", "youtube.com": "youtube", "youtu.be": "youtube",
    "wa.me": "whatsapp",
}
TWO_LEVEL = {"co", "ac", "go", "or", "in", "net", "mi", "com", "org"}


def registrable(host):
    host = (host or "").lower().split(":")[0].strip(".")
    parts = host.split(".")
    if len(parts) <= 2:
        return host
    if len(parts[-1]) == 2 and parts[-2] in TWO_LEVEL:
        return ".".join(parts[-3:])
    return ".".join(parts[-2:])


def norm_url(url):
    url = (url or "").strip()
    if not url:
        return None
    if "://" not in url:
        url = "http://" + url
    try:
        p = urllib.parse.urlsplit(url)
    except ValueError:
        return None
    if p.scheme not in ("http", "https") or not p.netloc:
        return None
    return urllib.parse.urlunsplit(p)


def url_kind(url):
    """facebook / instagram / line / … for walled-garden links, else None."""
    if not url:
        return None
    p = urllib.parse.urlsplit(url)
    return SOCIAL_HOSTS.get(registrable(p.netloc)) or SOCIAL_HOSTS.get(
        p.netloc.lower().replace("www.", ""))


def verdict(url):
    u = norm_url(url)
    if not u:
        return {}
    v = LINK_HEALTH.get(u)
    if v is None:
        # check_links.py keys a bare host as "http://host/" and a record may
        # say "http://host" — one slash apart, so 14 sites it had marked dead
        # in July still got a live pill, and the publish gate held the walk
        # shut for two days over them (2026-09-10). Look both ways.
        alt = u + "/" if not urllib.parse.urlsplit(u).path else u.rstrip("/")
        v = LINK_HEALTH.get(alt)
    return v or {}


def pretty_url(url):
    """Show a domain, not a 90-character tracking-parameter novel."""
    p = urllib.parse.urlsplit(norm_url(url) or url)
    out = p.netloc.replace("www.", "") + (p.path.rstrip("/") if p.path != "/" else "")
    return out if len(out) <= 42 else out[:40] + "…"


def handle_of(url, prefix="@"):
    seg = (norm_url(url) or url).rstrip("/").rsplit("/", 1)[-1]
    seg = urllib.parse.unquote(seg).lstrip("@")
    if seg.startswith("profile.php") or not seg:
        return None
    return prefix + (seg if len(seg) <= 28 else seg[:26] + "…")


BROKEN_WHY = {
    "tls": ("ใบรับรองความปลอดภัยหมดอายุ", "security certificate no longer valid"),
    "dns": ("โดเมนไม่มีแล้ว", "the domain is gone"),
    "down": ("เครื่องแม่ข่ายไม่ตอบ", "the server does not answer"),
    "timeout": ("เครื่องแม่ข่ายไม่ตอบ", "the server does not answer"),
    "gone": ("หน้านั้นไม่มีแล้ว", "that page is no longer there"),
    "http-error": ("เปิดไม่ได้", "the site returns an error"),
    "server-error": ("เครื่องแม่ข่ายมีปัญหา", "the server reports an error"),
    "parked": ("โดเมนถูกปล่อยว่าง/ประกาศขาย", "the domain is parked or for sale"),
    "empty": ("หน้าว่างเปล่า", "the page comes back empty"),
    "error": ("เปิดไม่ได้", "the link could not be opened"),
}


# rowline_layer.index_phone's split: one field often holds two numbers.
_TEL_SPLIT = re.compile(r"[,;/]|\s{2,}")


def _tel_digits(s):
    """One number's digits by the list row's own rule (rowline_layer.index_phone),
    called, not copied, so row and page cannot drift."""
    return rowline_layer.index_phone({"phone": re.sub(r"\D", "", str(s or ""))})


def fmt_tel(s):
    """A number printed the way the list row prints it (rowline_layer telText).

    One record showed two forms: 089-263-7243 on the search row, +66892637243
    on its own page. 3-3-4 for a mobile, 3-3-3 for a landline; a second
    number on the field is printed the same way after a slash. A part that
    does not group — an extension, a range, a typo — keeps its own text, and
    a field with no number in it at all is printed as written.
    """
    raw = str(s or "").strip()
    out, read = [], False
    for part in _TEL_SPLIT.split(raw):
        part = part.strip()
        if not part:
            continue
        d = _tel_digits(part)
        read = read or bool(d)
        if d and len(d) in (9, 10) and d[0] == "0":
            out.append(d[:3] + "-" + d[3:6] + "-" + d[6:])
        elif d and part.startswith("+") and d[0] != "0":
            out.append("+" + d)  # a foreign number keeps the + it is dialled with
        else:
            out.append(part)
    return " / ".join(out) if read else raw


def tel_href(s):
    """The first number as a tel: target, E.164 (rowline_layer telHref)."""
    first = next((x.strip() for x in _TEL_SPLIT.split(str(s or "")) if x.strip()), "")
    d = _tel_digits(first)
    if not d:
        return "tel:" + str(s or "").replace(" ", "")
    if d[0] == "0":
        return "tel:+66" + d[1:]
    return "tel:" + ("+" if first.startswith("+") else "") + d


def channels(r):
    """Every way to reach this place, best-first, plus anything we had to retire.

    Order follows how people here actually get an answer: a phone is picked up,
    a LINE message is read, a Facebook page is current. A website — when it
    works at all — is usually the least current of the four.
    """
    a = dict(r.get("attrs") or {})  # local: normalizing must not rewrite the record
    live, retired, seen = [], [], set()

    # Owner-claimed facts (importers/sync_claims.py -> data/claims.json) win
    # over anything crawled — the owner is the authority on their own number.
    # Assigned directly, not setdefault, so a claim overrides a stale OSM value.
    claim = CLAIMS.get(r["id"])
    claimed_kinds, claim_web = set(), None
    phone = r.get("phone")
    if claim:
        if claim.get("phone"):
            phone, claimed_kinds = claim["phone"], claimed_kinds | {"phone"}
        for k in ("lineId", "facebook", "instagram", "whatsapp", "email"):
            if claim.get(k):
                a[k] = claim[k]
                claimed_kinds.add("line" if k == "lineId" else k)
        cu = norm_url(claim.get("website"))
        if cu:
            k = url_kind(cu)
            if k in ("facebook", "instagram"):
                a[k] = cu
            elif k == "line":
                a["lineUrl"] = cu
            else:
                claim_web = cu
            claimed_kinds.add(k or "web")

    # A fact recovered from the archived copy of a site that has since died is
    # true as of the snapshot, not as of today, and it must not sit on the page
    # looking like a number somebody just answered. enrich_wayback.py stamps
    # `archivedOn` per field; this turns that into the words a reader needs.
    archived = {}
    for _f, _p in (r.get("enrichedFields") or {}).items():
        if (_p or {}).get("license") == "archived-official-site" and _p.get("archivedOn"):
            _when = _p["archivedOn"][:4]
            _kind = {"phone": "phone", "attrs.lineUrl": "line", "attrs.email": "email",
                     "attrs.facebook": "facebook", "attrs.instagram": "instagram",
                     "attrs.whatsapp": "whatsapp"}.get(_f)
            if _kind:
                archived[_kind] = _when

    # Reader-supplied fields (facts.py) carry the date a person approved them.
    _rf = a.get("readerFacts") or {}
    reader_kinds = {k: _rf[f] for f, k in (("phone", "phone"), ("line", "line"), ("website", "web")) if _rf.get(f)}

    def add(kind, label_th, label_en, href, text, badge=None, cls=None):
        if href in seen:
            return
        seen.add(href)
        if kind in claimed_kinds and badge is None:
            badge = ("ยืนยันโดยเจ้าของ", "owner-confirmed")
        elif kind in reader_kinds and badge is None:
            badge = (f"จากผู้อ่าน ตรวจแล้ว {reader_kinds[kind]}", f"from a reader, checked {reader_kinds[kind]}")
        elif kind in archived and badge is None:
            badge = (f"จากเว็บเดิม เก็บถาวรปี {archived[kind]}",
                     f"from their old site, archived {archived[kind]}")
        live.append({"kind": kind, "cls": cls or kind, "th": label_th, "en": label_en,
                     "href": href, "text": text, "badge": badge})

    # A "website" that is really a Facebook page is filed as Facebook. That is
    # what it is, and it is the single most common shape of a Thai business's
    # web presence — pretending otherwise buries the channel that works.
    sites = []
    for field, raw in (("website", r.get("website")), ("brandWebsite", a.get("brandWebsite")),
                       ("website", a.get("website"))):
        u = norm_url(raw)
        if not u:
            continue
        kind = url_kind(u)
        if kind in ("facebook", "instagram"):
            a.setdefault(kind, u)
        elif kind == "line":
            a.setdefault("lineUrl", u)
        elif kind is None:
            sites.append((field, u))

    if phone:
        ph = phone.split(";")[0].strip()
        add("phone", "โทร", "Phone", "tel:" + ph.replace(" ", ""), ph)
    line_id = a.get("lineId")
    if line_id:
        lid = line_id.lstrip("@~")
        add("line", "LINE", "LINE", f"https://line.me/R/ti/p/~{lid}", "@" + lid)
    elif a.get("lineUrl"):
        add("line", "LINE", "LINE", a["lineUrl"], handle_of(a["lineUrl"]) or "LINE")

    fb = fb_url_of(a.get("facebook"))
    if fb:
        add("facebook", "เฟซบุ๊ก", "Facebook", fb, handle_of(fb) or "Facebook")

    # An owner-claimed website is a first-party assertion, not a crawled field —
    # it skips the link-health check entirely and is trusted on the owner's say-so.
    if claim_web:
        add("web", "เว็บไซต์", "Website", claim_web, pretty_url(claim_web), cls="web")

    for field, u in sites:
        v = verdict(u)
        st = v.get("status")
        if st in BROKEN:
            retired.append({"url": u, "status": st, "detail": v.get("detail", ""),
                            "wayback": v.get("wayback") or {},
                            "checked": v.get("checkedAt", LINK_HEALTH_DATE), "field": field})
            continue
        if st == "moved-social":
            target = v.get("final") or u
            k = v.get("channel") or "facebook"
            add(k, {"facebook": "เฟซบุ๊ก"}.get(k, k.title()), k.title(), target,
                handle_of(target) or k.title(),
                badge=("เว็บเดิมพามาที่นี่", "their old site forwards here"))
            continue
        badge = None
        if st == "redirect-offsite" and v.get("to"):
            badge = ("ไปที่ " + v["to"], "now at " + v["to"])
        elif not st:
            badge = ("ยังไม่ได้ตรวจ", "not checked yet")
        label_th, label_en = ("เว็บของแบรนด์", "Brand site") if field == "brandWebsite" \
            else ("เว็บไซต์", "Website")
        add("web", label_th, label_en, u, pretty_url(u), badge=badge, cls="web")

    ig = a.get("instagram")
    if ig:
        ig_url = ig if ig.startswith("http") else "https://www.instagram.com/" + ig.lstrip("@/")
        add("instagram", "อินสตาแกรม", "Instagram", ig_url, handle_of(ig_url) or "Instagram")
    wa = a.get("whatsapp")
    if wa:
        add("whatsapp", "WhatsApp", "WhatsApp",
            "https://wa.me/" + wa.lstrip("+").replace(" ", ""), wa)
    em = a.get("email")
    if em:
        add("email", "อีเมล", "Email", "mailto:" + em, em)
    return live, retired

