def collect_photos():
    """assets/photos/<record-id>.(jpg|jpeg|png|webp) -> {id: filename}."""
    out = {}
    if PHOTOS_SRC.exists():
        for f in sorted(PHOTOS_SRC.iterdir()):
            if f.suffix.lower() in (".jpg", ".jpeg", ".png", ".webp"):
                out[f.stem] = f.name
    return out


