# ---- credit links: who gets a followed link -------------------------------
# The polite backlink was the point of the whole aggregation move — "help our
# site grow and their site grow" — but every credit link on this site has
# carried rel="nofollow", which passes no standing at all. So: a per-source
# allowlist, and the rule behind it is who we OWE.
#
# FOLLOWED — the publishers whose data is on the page a reader is reading:
# Thailand's open-data hosts and the departments that publish through them,
# and the one private directory this site actually took names and addresses
# from (weed.th, which invited crawlers and got 658 attributed links). Linking
# to a .go.th register cannot hurt this site's standing and does help theirs,
# which is the whole bargain.
#
# NOFOLLOW — everything else, unchanged: a place's own website, a social page,
# an "also catalogued by" courtesy link to a directory we did not take from.
# Those are links we publish for the reader's sake, not endorsements we can
# vouch for, and a followed link to a domain that later turns into something
# else is a promise we cannot keep.
FOLLOW_HOSTS = (
    ".go.th",            # every Thai government host, incl. data.go.th + gdcatalog
    "data.go.th", "gdcatalog.go.th",
    "openstreetmap.org", "wikidata.org", "wikipedia.org", "wikimedia.org",
    "weed.th",           # the aggregator we took names and addresses from
)


def credit_rel(url):
    """rel for a SOURCE-CREDIT link. Followed for the publishers we owe."""
    host = urllib.parse.urlsplit(url or "").netloc.lower().split(":")[0]
    if host and any(host == h.lstrip(".") or host.endswith(h) for h in FOLLOW_HOSTS):
        return ' rel="noopener"'
    return ' rel="nofollow noopener"'


_OH_RULE = re.compile(
    r"^(?:Mo|Tu|We|Th|Fr|Sa|Su)(?:-(?:Mo|Tu|We|Th|Fr|Sa|Su))?(?:,(?:Mo|Tu|We|Th|Fr|Sa|Su)(?:-(?:Mo|Tu|We|Th|Fr|Sa|Su))?)*"
    r"\s+\d\d:\d\d-\d\d:\d\d(?:,\s*\d\d:\d\d-\d\d:\d\d)*$")


def postal_address(r):
    """schema.org PostalAddress from a record, or None when it holds no address."""
    pal = r.get("attrs") or {}
    if not (r.get("address") or pal.get("tambon") or pal.get("amphoe")):
        return None
    addr = {"@type": "PostalAddress", "addressCountry": "TH"}
    if r.get("address"):
        addr["streetAddress"] = r["address"]
    locality = pal.get("tambon") or pal.get("amphoe")
    if isinstance(locality, str) and locality.strip():
        addr["addressLocality"] = locality.strip()
    region = FEST_PROV_LABEL.get(r.get("province"))
    if region:
        addr["addressRegion"] = region[1]
    if pal.get("postcode"):
        addr["postalCode"] = str(pal["postcode"])
    return addr


def ld_json(r, path, photo_file):
    obj = {
        "@context": "https://schema.org",
        "@type": next((SCHEMA_TYPE_SUB[s] for s in (r.get("sub") or [])
                       if s in SCHEMA_TYPE_SUB),
                      SCHEMA_TYPE.get(r["cat"][0], "LocalBusiness")),
        "name": name_of(r),
        # The other name, where there is one. schema.org `name` takes a single
        # string, so the second language belongs here rather than jammed into
        # the first with a separator no consumer agreed to.
        **({"alternateName": [n for n in name_pair(r) if n and n != name_of(r)]}
           if [n for n in name_pair(r) if n and n != name_of(r)] else {}),
        "url": BASE + path,
        # Only a real photograph. Publishing the ant or the wat drawing here
        # told every crawler that this shop's picture is a line drawing of a
        # temple, which is a false statement about a named business.
        **({"image": BASE + f"photos/{photo_file}"} if photo_file else {}),
    }
    # A real second name, not just the primary name re-typed in Latin script —
    # half of what a place gets searched by is whichever language the
    # searcher is typing in, and Google's entity matching reads alternateName.
    nen = r.get("nameEn")
    if nen and nen != r.get("name") and nen != obj["name"]:
        obj["alternateName"] = nen
    # A POSTAL ADDRESS HAS PARTS. Until 2026-09-08 this shipped one string in
    # streetAddress and nothing else, because a locality and a postcode existed
    # on 3.7% and 3.7% of records. derive.py reads both out of the address text
    # the record already carried, so ~20% now have a district and 7,542 a
    # postcode — and addressLocality/postalCode are exactly the two fields both
    # Google's rich results and every LLM extractor read (G3 in the arrivals
    # note). The region is ours by construction: this directory is two provinces.
    _addr = postal_address(r)
    if _addr:
        obj["address"] = _addr
    if r.get("lat") is not None:
        obj["geo"] = {"@type": "GeoCoordinates", "latitude": r["lat"], "longitude": r["lng"]}
    # This page is the citable record for the place — say so, and only vouch for
    # links that were verified to answer. Publishing a dead URL as sameAs feeds
    # the same rot everywhere downstream.
    obj["mainEntityOfPage"] = {"@type": "WebPage", "@id": BASE + path}
    live, _retired = channels(r)
    phone_channel = next((c for c in live if c["kind"] == "phone"), None)
    if phone_channel:
        obj["telephone"] = phone_channel["text"]
    # HOURS THE PAGE ALREADY PRINTS — 2026-09-23
    # 4,403 records carry opening hours and the place page shows them, but this
    # block never did, so no engine reading schema.org could see a single one.
    # Same order as the page: the owner's confirmed hours first, then the
    # record's. Two kinds stay page-only. Hours lifted from an archived copy of a
    # dead site are printed with their year as a lead, and schema.org has no
    # place for that caveat, so they are not stated here as current fact. And a
    # value not already in schema.org's own form ("Mo-Su 08:00-18:00", ";" between
    # rules) is left out rather than rewritten into something the owner never said.
    _claim = CLAIMS.get(r.get("id")) or {}
    _hours = _claim.get("hours") or r.get("hours")
    _archived = (((r.get("enrichedFields") or {}).get("hours") or {}).get("license")
                 == "archived-official-site") and not _claim.get("hours")
    if _hours and not _archived:
        _rules = [x.strip() for x in str(_hours).split(";") if x.strip()]
        if _rules and all(x == "24/7" or _OH_RULE.match(x) for x in _rules):
            obj["openingHours"] = ["Mo-Su 00:00-23:59" if x == "24/7" else x
                                   for x in _rules]
    same_as = [c["href"] for c in live if c["href"].startswith("http")]
    # Wikipedia and Wikidata are what sameAs was invented for — the canonical
    # identifiers for the same real thing. They were sitting unused in the OSM
    # tags. Only the ones about this place: the brand's entity describes the
    # chain, and asserting it here would say a branch and its parent company are
    # one entity, which is exactly the claim sameAs makes.
    # Not every marked link qualifies. sameAs asserts identity, so a Michelin
    # article listing eleven restaurants and a Commons file page — both good
    # reading, both marked on the page — would be false here.
    for x in elsewhere(r):
        if x.get("identity") and x["url"] not in same_as:
            same_as.append(x["url"])
    if same_as:
        obj["sameAs"] = same_as
    return f'<script type="application/ld+json">{json.dumps(obj, ensure_ascii=False)}</script>'


def breadcrumb_ld(items):
    """items: (name, url) pairs, root ("หน้าแรก"/Home) first, current page last —
    the same trail the visible crumbs render, so the two never disagree."""
    obj = {
        "@context": "https://schema.org",
        "@type": "BreadcrumbList",
        "itemListElement": [
            {"@type": "ListItem", "position": i + 1, "name": name, "item": url}
            for i, (name, url) in enumerate(items)
        ],
    }
    return f'<script type="application/ld+json">{json.dumps(obj, ensure_ascii=False)}</script>'


