    ("wifi", "ไวไฟ", "Wi-Fi"),
    ("airConditioning", "แอร์", "air conditioning"),
    ("outdoorSeating", "ที่นั่งด้านนอก", "outdoor seating"),
    ("indoorSeating", "ที่นั่งด้านใน", "indoor seating"),
    ("toilets", "ห้องน้ำ", "toilets"),
